#include "piper_workbench/main_window.hpp"
#include "piper_workbench/backend_client.hpp"
using namespace Ui;
QWidget *MainWindow::makeLogs(){
 auto *page=new QWidget;page->setObjectName("page");auto *layout=new QVBoxLayout(page);layout->setContentsMargins(20,20,20,16);layout->addWidget(text("运行日志","pageTitle"));auto *tabs=new QTabWidget;layout->addWidget(tabs,1);auto *logs=new QWidget;tabs->addTab(logs,"统一日志");auto *ll=new QVBoxLayout(logs);ll->setContentsMargins(0,12,0,0);auto *bar=new QHBoxLayout;
 logTime_=new QComboBox;logTime_->addItems({"最近一小时","最近一天","全部时间"});bar->addWidget(logTime_);logSource_=new QComboBox;logSource_->setEditable(true);logSource_->addItems({"全部来源","arm","camera:d455","camera:dabai","detector:dual","action","工作台"});logLevel_=new QComboBox;logLevel_->addItems({"全部级别","INFO","WARN","ERROR"});logSearch_=new QLineEdit;logSearch_->setPlaceholderText("搜索关键词、ROS 名称或错误原文");logPause_=new QCheckBox("暂停滚动");bar->addWidget(logSource_);bar->addWidget(logLevel_);bar->addWidget(logSearch_,1);bar->addWidget(logPause_);
 for(QString label:{"读取最近日志","导出筛选结果","打开日志目录","打开历史文件"}){auto *b=button(label);bar->addWidget(b);connect(b,&QPushButton::clicked,this,[this,label]{if(label=="打开日志目录"){showFile(QString::fromLocal8Bit(qgetenv("AGX_ARM_WS"))+"/log");return;}if(label=="打开历史文件"){auto path=QFileDialog::getOpenFileName(this,"读取历史原始日志",QString::fromLocal8Bit(qgetenv("AGX_ARM_WS"))+"/log");if(path.isEmpty())return;backend_->call("logs.history",{{"path",path}},[this](QJsonValue v){logDetail_->setPlainText(v.toObject()["text"].toString());});return;}QJsonObject filter{{"since",logTime_->currentIndex()==2?0.:QDateTime::currentMSecsSinceEpoch()/1000.-(logTime_->currentIndex()==0?3600.:86400.)},{"source",logSource_->currentText()=="全部来源"?"":logSource_->currentText()},{"level",logLevel_->currentIndex()==0?"":logLevel_->currentText()},{"keyword",logSearch_->text()}};backend_->call(label=="导出筛选结果"?"logs.export":"logs.subscribe",filter,[this,label](QJsonValue v){if(label=="导出筛选结果"){toast_->setText("日志已导出："+v.toObject()["path"].toString());return;}logRows_=v.toArray();filterLogs();});});}ll->addLayout(bar);
 auto *split=new QSplitter;auto *sources=card("日志来源");logSources_=new QListWidget;logSources_->setObjectName("sources");logSources_->setMaximumWidth(180);static_cast<QVBoxLayout *>(sources->layout())->addWidget(logSources_,1);split->addWidget(sources);connect(logSources_,&QListWidget::itemClicked,this,[this](QListWidgetItem *item){logSource_->setCurrentText(item->data(Qt::UserRole).toString());filterLogs();});auto *center=card("日志流 · 最近 10000 条");logTable_=new QTableWidget(0,4);logTable_->setHorizontalHeaderLabels({"时间","级别","来源","原始消息"});logTable_->horizontalHeader()->setSectionResizeMode(QHeaderView::ResizeToContents);logTable_->horizontalHeader()->setSectionResizeMode(3,QHeaderView::Stretch);logTable_->horizontalHeader()->setSectionResizeMode(2,QHeaderView::Interactive);logTable_->setColumnWidth(2,160);logTable_->setEditTriggers(QAbstractItemView::NoEditTriggers);logTable_->setSelectionBehavior(QAbstractItemView::SelectRows);logTable_->verticalHeader()->hide();static_cast<QVBoxLayout *>(center->layout())->addWidget(logTable_,1);split->addWidget(center);auto *right=card("原文详情");auto *rl=static_cast<QVBoxLayout *>(right->layout());logMetadata_=text("选中日志查看来源、时间、PID 与会话");rl->addWidget(logMetadata_);logDetail_=new QPlainTextEdit;logDetail_->setReadOnly(true);rl->addWidget(logDetail_,1);auto *copy=button("复制原文",false,"logs");rl->addWidget(copy);connect(copy,&QPushButton::clicked,this,[this]{qApp->clipboard()->setText(logDetail_->toPlainText());});split->addWidget(right);split->setSizes({180,780,330});ll->addWidget(split,1);
 connect(logTable_,&QTableWidget::cellClicked,this,[this](int r,int){logDetail_->setPlainText(logTable_->item(r,3)->data(Qt::UserRole).toString());logMetadata_->setText(logTable_->item(r,3)->data(Qt::UserRole+1).toString());});connect(logTime_,qOverload<int>(&QComboBox::currentIndexChanged),this,[this]{filterLogs();});connect(logSearch_,&QLineEdit::textChanged,this,[this]{filterLogs();});connect(logSource_,&QComboBox::currentTextChanged,this,[this]{filterLogs();});connect(logLevel_,qOverload<int>(&QComboBox::currentIndexChanged),this,[this]{filterLogs();});
 auto *diagnostic=new QWidget;auto *dl=new QHBoxLayout(diagnostic);auto *source=card("动态抓取诊断报告");auto *sl=static_cast<QVBoxLayout *>(source->layout());auto *reload=button("刷新报告列表",false,"refresh");sl->addWidget(reload);diagnostics_=new QListWidget;sl->addWidget(diagnostics_,1);dl->addWidget(source,1);auto *report=card("报告原始字段与阶段记录");auto *metrics=new QComboBox;metrics->addItems({"TCP 跟踪误差 (mm)","TCP Z：蓝色反馈 / 灰色目标 (mm)","夹爪开度 (mm)"});static_cast<QVBoxLayout *>(report->layout())->addWidget(metrics);auto *plot=new TracePlot;static_cast<QVBoxLayout *>(report->layout())->addWidget(plot);connect(metrics,qOverload<int>(&QComboBox::currentIndexChanged),plot,[plot](int i){plot->metric=i;plot->update();});diagnosticText_=new QPlainTextEdit;diagnosticText_->setReadOnly(true);static_cast<QVBoxLayout *>(report->layout())->addWidget(diagnosticText_,1);dl->addWidget(report,3);tabs->addTab(diagnostic,"动态抓取诊断");connect(reload,&QPushButton::clicked,this,[this]{backend_->call("diagnostics.list",{},[this](QJsonValue v){diagnostics_->clear();for(auto row:v.toArray()){auto *item=new QListWidgetItem(QFileInfo(row.toString()).fileName(),diagnostics_);item->setData(Qt::UserRole,row.toString());}});});connect(diagnostics_,&QListWidget::itemClicked,this,[this,plot](QListWidgetItem *item){backend_->call("diagnostics.read",{{"path",item->data(Qt::UserRole).toString()}},[this,plot](QJsonValue v){plot->report=v.toObject();plot->update();diagnosticText_->setPlainText(QJsonDocument(v.toObject()).toJson(QJsonDocument::Indented));});});return page;
}
void MainWindow::logRow(QJsonObject row){logRows_.append(row);while(logRows_.size()>10000)logRows_.removeFirst();logsDirty_=true;}
void MainWindow::filterLogs(){
 QMap<QString,int> sources;for(auto value:logRows_)sources[value.toObject()["source"].toString()]++;auto selected=logSource_->currentText();logSources_->clear();auto *all=new QListWidgetItem("全部来源  "+QString::number(logRows_.size()),logSources_);all->setData(Qt::UserRole,"全部来源");for(auto it=sources.begin();it!=sources.end();++it){auto *item=new QListWidgetItem(it.key()+"  "+QString::number(it.value()),logSources_);item->setData(Qt::UserRole,it.key());item->setToolTip(it.key());}
 logTable_->setRowCount(0);for(auto value:logRows_){auto row=value.toObject();QString source=row["source"].toString(),level=row["level"].toString(),message=row["text"].toString();if(logSource_->currentText()!="全部来源"&&!source.contains(logSource_->currentText()))continue;if(logTime_->currentIndex()!=2&&row["time"].toDouble()<QDateTime::currentMSecsSinceEpoch()/1000.-(logTime_->currentIndex()==0?3600.:86400.))continue;if(logLevel_->currentIndex()!=0&&level!=logLevel_->currentText())continue;if(!message.contains(logSearch_->text(),Qt::CaseInsensitive))continue;int r=logTable_->rowCount();logTable_->insertRow(r);QStringList cols={QDateTime::fromMSecsSinceEpoch(qint64(row["time"].toDouble()*1000)).toString("HH:mm:ss.zzz"),level,source,message.section('\n',0,0)};for(int i=0;i<4;++i)logTable_->setItem(r,i,new QTableWidgetItem(cols[i]));logTable_->item(r,3)->setData(Qt::UserRole,message);logTable_->item(r,3)->setData(Qt::UserRole+1,QString::fromUtf8(QJsonDocument(row).toJson(QJsonDocument::Compact)));}
 if(!logPause_->isChecked())logTable_->scrollToBottom();
}
